import{_ as n,o as t,c as r,a2 as a}from"./chunks/framework.DuPBmefI.js";const u=JSON.parse('{"title":"香港加拿大国际学校 · 年份未注明 · 幼儿预备班 · 面试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"canadian-international","school_zh":"香港加拿大国际学校","school_en":"Canadian International School of Hong Kong","grade":"pn","year":"unknown","year_label":"年份未注明","type":"interview","title":"香港加拿大国际学校 · 年份未注明 · 幼儿预备班 · 面试","anonymous":true,"source_ids":["INT-CDNIS-PN-FAMILY","INT-CDNIS-PN-HISTORICAL"],"rounds":["unknown"]},"headers":[],"relativePath":"reports/canadian-international/pn/unknown-interview.md","filePath":"reports/canadian-international/pn/unknown-interview.md"}'),e={name:"reports/canadian-international/pn/unknown-interview.md"};function s(p,o,i,c,l,d){return t(),r("div",null,[...o[0]||(o[0]=[a('<h1 id="香港加拿大国际学校-·-年份未注明-·-幼儿预备班-·-面试" tabindex="-1">香港加拿大国际学校 · 年份未注明 · 幼儿预备班 · 面试 <a class="header-anchor" href="#香港加拿大国际学校-·-年份未注明-·-幼儿预备班-·-面试" aria-label="Permalink to &quot;香港加拿大国际学校 · 年份未注明 · 幼儿预备班 · 面试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/canadian-international">← 返回香港加拿大国际学校资料库</a></p><blockquote><p>以下内容根据考试及面试资料整理，已作匿名化与书面化处理，非逐字实录。具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-int-cdnis-pn-family" tabindex="-1">资料来源：香港加拿大国际-PN班.pdf <a class="header-anchor" href="#record-int-cdnis-pn-family" aria-label="Permalink to &quot;资料来源：香港加拿大国际-PN班.pdf {#record-int-cdnis-pn-family}&quot;">​</a></h2><p><strong>资料类型：</strong> 家长考后反馈</p><p><strong>入学途径：</strong> 未注明</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="轮次未注明-·-请以当次考试通知为准" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>幼儿互动：</strong> 中文、英语</p><p><strong>入场与自由活动</strong></p><p>进入教室后，老师先询问孩子的名字。教室分三处摆放积木、拼图和画纸，让孩子自由选择活动；一位中文老师及一位英文老师观察表现并作记录。</p><p><strong>活动中的交流</strong></p><p>老师在游戏过程中与孩子交流，例如询问是否会唱英文儿歌《Row, Row, Row Your Boat》。</p></blockquote><blockquote><p><strong>运动活动：</strong></p><p><strong>大肌肉活动与球类互动</strong></p><p>孩子随老师前往中央大厅，进行钻洞、走独木桥、踩彩色板及滑滑梯等活动。该名孩子完成后，老师又邀请其踢球；孩子当时接住了家长抛出的球，没有展示平时在家的踢球表现。</p></blockquote><blockquote><p><strong>集体互动：</strong> 语言未注明</p><p><strong>故事、动物指认与歌唱动作</strong></p><p>返回室内后进入围坐活动（circle time）。老师讲述农场故事，让孩子指认书中的动物，再带领大家唱歌及做动作。</p></blockquote><blockquote><p><strong>学生与家长反馈：</strong></p><p><strong>从拘谨到逐渐投入</strong></p><p>家长反馈，孩子与手足分开参加活动后，起初低头不回应姓名提问；面对熟悉的儿歌，也因害羞未能表现。运动环节完成较快，故事和歌唱环节逐渐放松，结束时主动向老师道别。</p><p><strong>不同孩子的现场表现</strong></p><p>同一家庭另一名孩子据家长转述，现场较主动，与老师相处愉快。家长喜欢学校环境及老师轻松、热情的互动方式，也感到陌生环境和面试时段对幼儿的状态有影响；该名较内向的孩子虽然起初拘谨，仍完成了活动，没有哭闹。</p></blockquote><h2 id="record-int-cdnis-pn-historical" tabindex="-1">资料来源：香港加拿大国际-PN班.pdf <a class="header-anchor" href="#record-int-cdnis-pn-historical" aria-label="Permalink to &quot;资料来源：香港加拿大国际-PN班.pdf {#record-int-cdnis-pn-historical}&quot;">​</a></h2><p><strong>资料类型：</strong> 机构整理的历史评估流程</p><p><strong>入学途径：</strong> 未注明</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="轮次未注明-·-请以当次考试通知为准-1" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准-1" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>入场安排：</strong></p><p><strong>分组与家长陪同</strong></p><p>往年流程先将孩子分组，家长可陪同进入教室。</p></blockquote><blockquote><p><strong>幼儿互动：</strong> 中文、英语</p><p><strong>自由游戏与社交观察</strong></p><p>孩子进行积木、画画等活动，一位中文老师和一位英文老师观察表现并评分。观察内容包括是否主动分享玩具、玩完后是否归位，以及是否向其他孩子打招呼。</p></blockquote><blockquote><p><strong>运动与集体活动：</strong> 语言未注明</p><p><strong>跟随指令与动作</strong></p><p>家长带孩子围圈走动，活动包括红绿灯游戏、走独木桥及踩色板。之后由老师读绘本，请孩子指认动物，或随音乐模仿老师的动作。</p></blockquote>',20)])])}const h=n(e,[["render",s]]);export{u as __pageData,h as default};
